// Node: Tách ảnh từ nhiều link (Đã bổ sung mảng 2 ảnh, Style & rich_content)

const rawOutput = $input.first()?.json?.output 
  || $input.first()?.json?.text 
  || $('AI Tự chọn ảnh').first()?.json?.output 
  || "";

const cleanJson = String(rawOutput)
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

let parsedData = {};
try {
  parsedData = JSON.parse(cleanJson);
} catch (e) {
  parsedData = {};
}

function getDirectUrl(fileId) {
  if (!fileId) return "";
  const match = String(fileId).match(/\/d\/([a-zA-Z0-9_-]+)|id=([a-zA-Z0-9_-]+)/);
  const cleanId = match ? (match[1] || match[2]) : fileId;
  return `https://drive.usercontent.google.com/download?id=${cleanId}&export=download`;
}

function toArray(val) {
  if (Array.isArray(val)) return val;
  if (val === undefined || val === null || val === "") return [];
  return [val];
}

// 1. LẤY MẢNG CÁC SLIDE VÀ THÔNG SỐ STYLE TỔNG
const selectedOpStr = parsedData.selectedOp || "Option 1";
const selectedStyle = parsedData.selected_style || "";
const styleSpec     = parsedData.style_spec || "";
const styleReason   = parsedData.style_reason || "";
const totalImages   = parsedData.total_images || 1;

const items = parsedData.items 
  || parsedData.selected_media 
  || parsedData.slides 
  || parsedData.option_1 
  || [];

// 2. LẤY THÔNG TIN THƯ MỤC DRIVE BÀI VIẾT
let driveFolderId = "";
try { driveFolderId = $('Tạo Folder Ảnh Cho Bài Viết1').first()?.json?.id || $('Search files and folders1').first()?.json?.id || ""; } catch (e) {}

let driveFolderLink = "";
try { driveFolderLink = $('Tạo Folder Ảnh Cho Bài Viết1').first()?.json?.webViewLink || $('Search files and folders1').first()?.json?.webViewLink || ""; } catch (e) {}
if (!driveFolderLink && driveFolderId) {
  driveFolderLink = `https://drive.google.com/drive/folders/${driveFolderId}`;
}

const resultItems = [];

// 3. LẶP QUA TỪNG SLIDE VÀ XUẤT RA DỮ LIỆU ĐẦY ĐỦ CHO CÁC NODE SAU
if (Array.isArray(items) && items.length > 0) {
  items.forEach((item, itemIdx) => {
    const rawIds    = toArray(item.raw_image_ids   || item.raw_image_id   || item.file_id);
    const rawNames  = toArray(item.raw_image_names || item.raw_image_name || item.file_name);
    const subLabels = toArray(item.sub_labels);

    const rawImages = rawIds.map((id, i) => ({
      id: id || "",
      name: rawNames[i] || "",
      url: getDirectUrl(id)
    }));

    resultItems.push({
      json: {
        slide_index: item.variant_no || item.slide_index || (itemIdx + 1),
        total_images: totalImages,
        selectedOp: selectedOpStr,

        // Thông số Style chốt sẵn
        selected_style: selectedStyle,
        style_spec: styleSpec,
        style_reason: styleReason,

        // 🟢 TRUYỀN ĐỦ MẢNG NHIỀU ẢNH SANG NODE VISUAL BRIEF VÀ TẢI BINARY:
        raw_image_ids:   rawIds,
        raw_image_names: rawNames,
        raw_images:      rawImages,
        raw_image_count: rawImages.length,

        // Biến đại diện cho ảnh chính đầu tiên (phục vụ ghi báo cáo Sheet)
        raw_image_1_id:   rawImages[0]?.id   || "",
        raw_image_1_name: rawImages[0]?.name || "",
        raw_image_1_url:  rawImages[0]?.url  || "",

        // Nội dung chữ & Bố cục
        headline: item.headline || "",
        subtext: item.subtext || item.match_reason || "",
        content_type: item.content_type || "",
        rich_content: item.rich_content || {},
        sub_labels: subLabels,
        template_hint: item.template_hint || "",
        footnote: item.footnote || "",
        layout_note: item.layout_note || "",

        // Thư mục Drive
        drive_folder_id: driveFolderId,
        drive_folder_link: driveFolderLink
      }
    });
  });
}

return resultItems.length > 0 ? resultItems : [{ json: { error: "Không tìm thấy dữ liệu slide từ node AI Tự chọn ảnh" } }];

const HOTLINE_TEXT = "0868 515 668";

function getDirectUrl(fileId) {
  if (!fileId) return "";
  const match = String(fileId).match(/\/d\/([a-zA-Z0-9_-]+)|id=([a-zA-Z0-9_-]+)/);
  const cleanId = match ? (match[1] || match[2]) : fileId;
  return `https://drive.usercontent.google.com/download?id=${cleanId}&export=download`;
}

async function fetchBinary(url) {
  if (!url) return null;
  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url,
      encoding: 'arraybuffer',
      returnFullResponse: true,
    });
    const buffer = Buffer.isBuffer(response.body) ? response.body : Buffer.from(response.body);
    const contentType = (response.headers && response.headers['content-type']) || 'image/jpeg';
    return { buffer, contentType };
  } catch (err) {
    console.log(`❌ Tải LỖI: ${url} | ${err.message}`);
    return null;
  }
}

const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  try {
    const j = { ...(items[i].json || {}) };
    const binary = {};

    const rawList = Array.isArray(j.raw_images) && j.raw_images.length > 0
      ? j.raw_images
      : [{ id: j.raw_image_1_id, url: j.raw_image_1_url }];

    for (let imgIdx = 0; imgIdx < rawList.length; imgIdx++) {
      const imgObj = rawList[imgIdx];
      const imgUrl = imgObj?.url || getDirectUrl(imgObj?.id);

      if (imgUrl) {
        const result = await fetchBinary.call(this, imgUrl);
        if (result) {
          const { buffer, contentType } = result;

          // ✅ 1. Lưu binary như cũ (cho các node khác dùng)
          binary[`raw_image_${imgIdx + 1}`] = await this.helpers.prepareBinaryData(buffer, undefined, contentType);
        }
      }
    }

    j.hotline_text = HOTLINE_TEXT;
    results.push({ json: j, binary, pairedItem: { item: i } });

  } catch (err) {
    console.log(`❌ Item ${i} lỗi: ${err.message}`);
    results.push({ json: { ...(items[i]?.json || {}), error: err.message }, binary: {}, pairedItem: { item: i } });
  }
}

return results;

// Node: Gom Ảnh & Dựng Bài (Chuẩn 100% cho cả 3 nhánh Switch)
const inputItems = $input.all();
const firstItem = inputItems[0]?.json || {};

// 1. Lấy thông tin bài viết gốc (Tự động lấy đúng nguồn từ bất kỳ nhánh nào)
let opt = firstItem.fullMessage ? firstItem : null;
if (!opt || !opt.fullMessage) {
  try {
    opt = $('Lấy Option content, đã có thời gian đăng').first().json;
  } catch (e) {
    opt = firstItem;
  }
}

// 2. Gom danh sách Facebook Photo IDs (chỉ lọc những ID ảnh hợp lệ từ bước upload FB)
const photoIds = inputItems
  .map(i => (i.json || {}).id)
  .filter(id => id && !String(id).startsWith('http') && String(id) !== String(opt.ID));

// 3. Dựng Body bài đăng gửi cho Facebook Graph API
const body = { message: opt.fullMessage || "" };

// Nếu có ảnh (từ nhánh Drive hoặc Direct URL) -> Gắn mảng Album ảnh
if (photoIds.length > 0) {
  body.attached_media = photoIds.map(id => ({ media_fbid: String(id) }));
}

return [{
  json: {
    ID: opt.ID,
    selectedOp: opt.selectedOp,
    photo_count: photoIds.length,
    fb_body: body
  }
}];

// Node: Xóa Metadata AI (Hỗ trợ lặp và xử lý TOÀN BỘ N ảnh)
const items = $input.all();
const result = [];

for (let index = 0; index < items.length; index++) {
  const item = items[index];
  const binaryPropName = 'data';

  // Nếu item không chứa file nhị phân ảnh thì giữ nguyên
  if (!item.binary || !item.binary[binaryPropName]) {
    result.push(item);
    continue;
  }

  // Lấy buffer của từng ảnh theo chỉ số index
  const buf = await this.helpers.getBinaryDataBuffer(index, binaryPropName);

  // Lọc xóa toàn bộ khối Exif / C2PA nhãn AI trong JPEG
  if (buf[0] === 0xFF && buf[1] === 0xD8) {
    const cleaned = [0xFF, 0xD8];
    let i = 2;
    while (i < buf.length) {
      if (buf[i] === 0xFF) {
        const marker = buf[i + 1];
        if (marker === 0xDA) { // SOS - Start of Scan (bắt đầu dữ liệu ảnh thực)
          for (let j = i; j < buf.length; j++) cleaned.push(buf[j]);
          break;
        }
        if (marker >= 0xE0 && marker <= 0xEF) { // APP0-APP15 (Khối chứa nhãn AI & Exif)
          const len = (buf[i + 2] << 8) + buf[i + 3];
          i += 2 + len;
          continue;
        }
      }
      cleaned.push(buf[i]);
      i++;
    }

    const cleanBinary = await this.helpers.prepareBinaryData(
      Buffer.from(cleaned),
      item.binary[binaryPropName].fileName || `cleaned_${index}.jpg`,
      'image/jpeg'
    );
    result.push({ json: item.json, binary: { [binaryPropName]: cleanBinary } });
  } else {
    result.push(item);
  }
}

